package com.sky.handler;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.beans.TypeMismatchException;
import com.sky.result.Result;

import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
class GlobalExceptionHandlerTest {

    @InjectMocks
    private GlobalExceptionHandler globalExceptionHandler;

    @Test
    @DisplayName("正向测试：TypeMismatchException处理器正确处理异常并返回预期错误消息")
    void testTypeMismatchExceptionHandler() {
        // Arrange: 创建TypeMismatchException实例，模拟输入"abc"导致的类型不匹配
        TypeMismatchException ex = new TypeMismatchException("abc", Long.class);

        // Act: 调用异常处理器
        Result<String> result = globalExceptionHandler.exceptionHandler(ex);

        // Assert: 验证返回的Result不为null，错误消息正确
        assertNotNull(result);
        assertEquals("请求参数类型错误", result.getMsg());
    }

    @Test
    @DisplayName("边界测试：修复后，原来导致NumberFormatException的输入现在能被捕获并返回错误响应")
    void testOriginalExceptionNowHandled() {
        // Arrange: 模拟原始异常情况，输入"abc"应该导致TypeMismatchException
        TypeMismatchException ex = new TypeMismatchException("abc", Long.class);

        // Act: 调用处理器，验证不会抛出未捕获异常
        assertDoesNotThrow(() -> {
            Result<String> result = globalExceptionHandler.exceptionHandler(ex);
            assertNotNull(result);
            assertEquals("请求参数类型错误", result.getMsg());
        });
    }
}
